import sys
from collections import defaultdict
import heapq

def main():
    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = read_ints()
    k = read_ints()
    offers = [read_ints() for _ in range(m)]

    # Sort offers by day
    offers.sort()

    # Priority queue to store the days when each type of microtransaction will be on sale
    sale_days = [[] for _ in range(n + 1)]
    for d, t in offers:
        heapq.heappush(sale_days[t], d)

    current_day = 0
    total_burles = 0

    # Dictionary to keep track of how many of each type of microtransaction Ivan has bought
    bought = [0] * (n + 1)

    # List to keep track of the next available sale day for each type of microtransaction
    next_sale_day = [float('inf')] * (n + 1)

    while True:
        # Check if Ivan has bought all microtransactions
        if all(bought[i] >= k[i - 1] for i in range(1, n + 1)):
            break

        # Ivan earns one burle each day
        total_burles += 1

        # Try to buy microtransactions on the current day
        for i in range(1, n + 1):
            if bought[i] < k[i - 1]:
                if next_sale_day[i] <= current_day:
                    # Buy at sale price
                    if total_burles >= 1:
                        total_burles -= 1
                        bought[i] += 1
                        if sale_days[i]:
                            next_sale_day[i] = heapq.heappop(sale_days[i])
                else:
                    # Buy at regular price
                    if total_burles >= 2:
                        total_burles -= 2
                        bought[i] += 1

        current_day += 1

    print(current_day)

if __name__ == "__main__":
    main()

